import { NextRequest, NextResponse } from "next/server";
import prisma from "@/lib/prisma";

export async function GET(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const { id } = await params;

    // Find album by id or slug
    const album = await prisma.album.findFirst({
      where: {
        OR: [{ id }, { slug: id }],
        isActive: true,
      },
      include: {
        label: {
          select: {
            id: true,
            name: true,
            slug: true,
          },
        },
        cover: {
          select: {
            id: true,
            path: true,
            blurDataUrl: true,
          },
        },
        genres: {
          include: {
            genre: {
              select: {
                id: true,
                name: true,
                slug: true,
                color: true,
              },
            },
          },
        },
        moods: {
          include: {
            mood: {
              select: {
                id: true,
                name: true,
                slug: true,
                color: true,
              },
            },
          },
        },
        artists: {
          include: {
            artist: {
              select: {
                id: true,
                name: true,
                slug: true,
              },
            },
          },
          orderBy: { order: "asc" },
        },
        tracks: {
          where: { isActive: true },
          include: {
            audio: {
              select: {
                path: true,
              },
            },
            genres: {
              include: {
                genre: {
                  select: {
                    name: true,
                    slug: true,
                  },
                },
              },
            },
            moods: {
              include: {
                mood: {
                  select: {
                    name: true,
                    slug: true,
                  },
                },
              },
            },
            instruments: {
              include: {
                instrument: {
                  select: {
                    name: true,
                    slug: true,
                  },
                },
              },
            },
            artists: {
              include: {
                artist: {
                  select: {
                    name: true,
                    slug: true,
                  },
                },
              },
            },
          },
          orderBy: [{ trackNumber: "asc" }, { order: "asc" }],
        },
      },
    });

    if (!album) {
      return NextResponse.json({ error: "Album not found" }, { status: 404 });
    }

    // Get similar albums (same genre)
    const mainGenreId = album.genres[0]?.genre.id;
    let similarAlbums: typeof album[] = [];

    if (mainGenreId) {
      similarAlbums = await prisma.album.findMany({
        where: {
          isActive: true,
          id: { not: album.id },
          genres: {
            some: {
              genreId: mainGenreId,
            },
          },
