import { NextRequest, NextResponse } from "next/server";
import prisma from "@/lib/prisma";

export async function GET(request: NextRequest) {
  try {
    const searchParams = request.nextUrl.searchParams;
    const limit = parseInt(searchParams.get("limit") || "50");
    const offset = parseInt(searchParams.get("offset") || "0");
    const albumId = searchParams.get("albumId");
    const genreSlug = searchParams.get("genre");
    const moodSlug = searchParams.get("mood");
    const instrumentSlug = searchParams.get("instrument");
    const minBpm = searchParams.get("minBpm");
    const maxBpm = searchParams.get("maxBpm");
    const minDuration = searchParams.get("minDuration");
    const maxDuration = searchParams.get("maxDuration");
    const isVocal = searchParams.get("isVocal");

    // Build where clause
    const where: Record<string, unknown> = {
      isActive: true,
      album: { isActive: true },
    };

    if (albumId) {
      where.albumId = albumId;
    }

    if (genreSlug) {
      where.genres = {
        some: {
          genre: { slug: genreSlug },
        },
      };
    }

    if (moodSlug) {
      where.moods = {
        some: {
          mood: { slug: moodSlug },
        },
      };
    }

    if (instrumentSlug) {
      where.instruments = {
        some: {
          instrument: { slug: instrumentSlug },
        },
      };
    }

    if (minBpm || maxBpm) {
      where.bpm = {};
      if (minBpm) (where.bpm as Record<string, number>).gte = parseInt(minBpm);
      if (maxBpm) (where.bpm as Record<string, number>).lte = parseInt(maxBpm);
    }

    if (minDuration || maxDuration) {
      where.duration = {};
      if (minDuration)
        (where.duration as Record<string, number>).gte = parseInt(minDuration);
      if (maxDuration)
        (where.duration as Record<string, number>).lte = parseInt(maxDuration);
    }

    if (isVocal !== null && isVocal !== undefined) {
      where.isVocal = isVocal === "true";
    }

    const [tracks, total] = await Promise.all([
      prisma.track.findMany({
        where,
        include: {
          album: {
            select: {
              id: true,
              title: true,
              slug: true,
              cover: {
                select: {
                  path: true,
                },
              },
            },
          },
          audio: {
            select: {
              path: true,
            },
          },
          genres: {
            include: {
              genre: {
                select: {
                  name: true,
                  slug: true,
                  color: true,
                },
              },
            },
          },
          moods: {
            include: {
              mood: {
                select: {
                  name: true,
                  slug: true,
                  color: true,
                },
              },
            },
          },
          instruments: {
            include: {
              instrument: {
                select: {
                  name: true,
                  slug: true,
                },
              },
            },
          },
        },
        orderBy: [{ album: { order: "asc" } }, { trackNumber: "asc" }],
        take: limit,
        skip: offset,
      }),
      prisma.track.count({ where }),
    ]);

    const transformedTracks = tracks.map((track) => ({
      id: track.id,
      slug: track.slug,
      title: track.title,
      duration: track.duration,
      bpm: track.bpm,
      key: track.key,
      isVocal: track.isVocal,
      audioUrl: track.audio?.path || track.previewUrl || null,
      waveform: track.waveform as number[] | null,
      albumId: track.album.id,
      albumTitle: track.album.title,
      albumSlug: track.album.slug,
      albumCover: track.album.cover?.path || "/images/placeholder-album.jpg",
      genres: track.genres.map((g) => g.genre.name),
      moods: track.moods.map((m) => m.mood.name),
      instruments: track.instruments.map((i) => i.instrument.name),
    }));

    return NextResponse.json({
      tracks: transformedTracks,
      pagination: {
        total,
        limit,
        offset,
        hasMore: offset + limit < total,
      },
    });
  } catch (error) {
    console.error("Error fetching tracks:", error);
    return NextResponse.json(
      { error: "Failed to fetch tracks" },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from "next/server";
import prisma from "@/lib/prisma";

export async function GET(request: NextRequest) {
  try {
    const searchParams = request.nextUrl.searchParams;
    const query = searchParams.get("q") || "";
    const limit = parseInt(searchParams.get("limit") || "20");
    const type = searchParams.get("type"); // all, albums, tracks, artists

    if (!query || query.length < 2) {
      return NextResponse.json({
        albums: [],
        tracks: [],
        artists: [],
        total: 0,
      });
    }

    const searchTerm = `%${query}%`;

    const results: {
      albums: unknown[];
      tracks: unknown[];
      artists: unknown[];
    } = {
      albums: [],
      tracks: [],
      artists: [],
    };

    // Search albums
    if (!type || type === "all" || type === "albums") {
      const albums = await prisma.album.findMany({
        where: {
          isActive: true,
          OR: [
            { title: { contains: query, mode: "insensitive" } },
            { description: { contains: query, mode: "insensitive" } },
            {
              artists: {
                some: {
                  artist: { name: { contains: query, mode: "insensitive" } },
                },
              },
            },
          ],
        },
        include: {
          label: {
            select: { name: true, slug: true },
          },
          cover: {
            select: { path: true },
          },
          genres: {
            include: {
              genre: {
                select: { name: true, slug: true, color: true },
              },
            },
          },
          artists: {
            include: {
              artist: {
                select: { name: true, slug: true },
              },
            },
          },
          _count: {
            select: { tracks: true },
          },
        },
        take: type === "albums" ? limit : 5,
        orderBy: { order: "asc" },
      });

      results.albums = albums.map((album) => ({
        id: album.id,
        slug: album.slug,
        title: album.title,
        cover: album.cover?.path || "/images/placeholder-album.jpg",
        label: album.label?.name || "Parigo",
        genres: album.genres.map((g) => g.genre.name),
        artists: album.artists.map((a) => a.artist.name),
        trackCount: album._count.tracks,
      }));
    }

    // Search tracks
    if (!type || type === "all" || type === "tracks") {
      const tracks = await prisma.track.findMany({
        where: {
          isActive: true,
          album: { isActive: true },
          OR: [
            { title: { contains: query, mode: "insensitive" } },
            {
              genres: {
                some: {
                  genre: { name: { contains: query, mode: "insensitive" } },
                },
              },
            },
            {
              moods: {
                some: {
                  mood: { name: { contains: query, mode: "insensitive" } },
                },
              },
            },
          ],
        },
        include: {
          album: {
            select: {
              id: true,
              title: true,
              slug: true,
              cover: { select: { path: true } },
            },
          },
          audio: { select: { path: true } },
          genres: {
            include: {
              genre: { select: { name: true } },
            },
          },
          moods: {
            include: {
              mood: { select: { name: true } },
            },
          },
        },
        take: type === "tracks" ? limit : 10,
        orderBy: { playCount: "desc" },
      });

      results.tracks = tracks.map((track) => ({
        id: track.id,
        slug: track.slug,
        title: track.title,
        duration: track.duration,
        bpm: track.bpm,
        isVocal: track.isVocal,
        audioUrl: track.audio?.path || track.previewUrl || null,
        waveform: track.waveform,
        albumId: track.album.id,
        albumTitle: track.album.title,
        albumSlug: track.album.slug,
        albumCover: track.album.cover?.path || "/images/placeholder-album.jpg",
        genres: track.genres.map((g) => g.genre.name),
        moods: track.moods.map((m) => m.mood.name),
      }));
    }

    // Search artists
    if (!type || type === "all" || type === "artists") {
      const artists = await prisma.artist.findMany({
        where: {
          isActive: true,
          name: { contains: query, mode: "insensitive" },
        },
        include: {
          image: { select: { path: true } },
          _count: {
            select: { albumCredits: true, trackCredits: true },
          },
        },
        take: type === "artists" ? limit : 5,
        orderBy: { order: "asc" },
      });

      results.artists = artists.map((artist) => ({
        id: artist.id,
        slug: artist.slug,
        name: artist.name,
        image: artist.image?.path || "/images/placeholder-artist.jpg",
        albumCount: artist._count.albumCredits,
        trackCount: artist._count.trackCredits,
      }));
    }

    return NextResponse.json({
      ...results,
      total:
        results.albums.length + results.tracks.length + results.artists.length,
      query,
    });
  } catch (error) {
    console.error("Error searching:", error);
    return NextResponse.json({ error: "Search failed" }, { status: 500 });
  }
}

