/**
 * Spotify API Client
 * Uses Client Credentials flow for server-side access
 */

interface SpotifyToken {
  access_token: string;
  token_type: string;
  expires_in: number;
  expires_at?: number;
}

interface SpotifyTrack {
  id: string;
  name: string;
  duration_ms: number;
  track_number: number;
  preview_url: string | null;
  external_ids?: {
    isrc?: string;
  };
  artists: Array<{
    id: string;
    name: string;
  }>;
}

interface SpotifyAlbum {
  id: string;
  name: string;
  release_date: string;
  total_tracks: number;
  images: Array<{
    url: string;
    height: number;
    width: number;
  }>;
  tracks: {
    items: SpotifyTrack[];
    total: number;
    next: string | null;
  };
}

let cachedToken: SpotifyToken | null = null;

/**
 * Get Spotify access token using Client Credentials flow
 */
export async function getSpotifyToken(): Promise<string> {
  // Check if we have a valid cached token
  if (cachedToken && cachedToken.expires_at && Date.now() < cachedToken.expires_at) {
    return cachedToken.access_token;
  }

  const clientId = process.env.SPOTIFY_CLIENT_ID;
  const clientSecret = process.env.SPOTIFY_CLIENT_SECRET;

  if (!clientId || !clientSecret) {
    throw new Error("Spotify credentials not configured");
  }

  const response = await fetch("https://accounts.spotify.com/api/token", {
    method: "POST",
    headers: {
      "Content-Type": "application/x-www-form-urlencoded",
      Authorization: `Basic ${Buffer.from(`${clientId}:${clientSecret}`).toString("base64")}`,
    },
    body: "grant_type=client_credentials",
  });

  if (!response.ok) {
    throw new Error(`Failed to get Spotify token: ${response.statusText}`);
  }

  const token: SpotifyToken = await response.json();

  // Cache the token with expiry time (subtract 60 seconds for safety margin)
  cachedToken = {
    ...token,
    expires_at: Date.now() + (token.expires_in - 60) * 1000,
  };

  return token.access_token;
}

/**
 * Fetch album details including tracks from Spotify
 */
export async function getSpotifyAlbum(albumId: string): Promise<SpotifyAlbum> {
  const token = await getSpotifyToken();

  const response = await fetch(`https://api.spotify.com/v1/albums/${albumId}`, {
    headers: {
      Authorization: `Bearer ${token}`,
    },
  });

  if (!response.ok) {
    if (response.status === 404) {
      throw new Error(`Album not found: ${albumId}`);
    }
    throw new Error(`Failed to fetch album: ${response.statusText}`);
  }

  return response.json();
}

/**
 * Fetch all tracks from an album (handles pagination)
 */
export async function getSpotifyAlbumTracks(albumId: string): Promise<SpotifyTrack[]> {
  const token = await getSpotifyToken();
  const tracks: SpotifyTrack[] = [];
  let nextUrl: string | null = `https://api.spotify.com/v1/albums/${albumId}/tracks?limit=50`;

  while (nextUrl) {
    const response = await fetch(nextUrl, {
      headers: {
        Authorization: `Bearer ${token}`,
      },
    });

    if (!response.ok) {
      throw new Error(`Failed to fetch tracks: ${response.statusText}`);
    }

    const data = await response.json();
    tracks.push(...data.items);
    nextUrl = data.next;
  }

  return tracks;
}

/**
 * Extract Spotify album ID from URL
 */
export function extractSpotifyAlbumId(url: string): string | null {
  // Handle various Spotify URL formats
  // https://open.spotify.com/album/5qe4qJH2y5Hu1pXZsBdDIN
  // https://open.spotify.com/intl-fr/album/5qe4qJH2y5Hu1pXZsBdDIN
  // spotify:album:5qe4qJH2y5Hu1pXZsBdDIN

  const patterns = [
    /spotify\.com\/(?:intl-[a-z]+\/)?album\/([a-zA-Z0-9]+)/,
    /spotify:album:([a-zA-Z0-9]+)/,
  ];

  for (const pattern of patterns) {
    const match = url.match(pattern);
    if (match) {
      return match[1];
    }
  }

  return null;
}

/**
 * Generate waveform data from audio analysis (simplified version)
 * In production, you would use Spotify's Audio Analysis API or process actual audio
 */
export function generateWaveformData(trackDuration: number, seed: number): number[] {
  const points = 100;
  const waveform: number[] = [];

  // Seeded random for reproducibility
  const seededRandom = (s: number) => {
    const x = Math.sin(s) * 10000;
    return x - Math.floor(x);
  };

  for (let i = 0; i < points; i++) {
    // Generate waveform-like data with envelope
    const position = i / points;
    const envelope = Math.sin(position * Math.PI); // Fade in/out
    const wave1 = Math.sin(position * 8 * Math.PI) * 0.3;
    const wave2 = Math.sin(position * 12 * Math.PI + seed) * 0.2;
    const noise = (seededRandom(seed + i) - 0.5) * 0.4;

    const value = 0.5 + (envelope * (wave1 + wave2 + noise));
    waveform.push(Math.max(0.1, Math.min(1, value)));
  }

  return waveform;
}

export type { SpotifyTrack, SpotifyAlbum };

/**
 * Script to fetch tracks from Spotify for all albums with Spotify URLs
 * Run with: pnpm tsx scripts/spotify/fetch-tracks.ts
 */

import { PrismaClient } from "@prisma/client";
import {
  extractSpotifyAlbumId,
  getSpotifyAlbumTracks,
  generateWaveformData,
  type SpotifyTrack,
} from "../../src/lib/spotify/client";

const prisma = new PrismaClient();

// Slugify function
function slugify(str: string): string {
  return str
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/(^-|-$)/g, "");
}

async function fetchTracksForAlbum(
  albumId: string,
  albumSlug: string,
  spotifyAlbumId: string
): Promise<number> {
  try {
    console.log(`  Fetching tracks for album: ${albumSlug} (${spotifyAlbumId})`);

    const spotifyTracks = await getSpotifyAlbumTracks(spotifyAlbumId);
    let created = 0;

    for (const spotifyTrack of spotifyTracks) {
      const trackSlug = `${albumSlug}-${slugify(spotifyTrack.name)}`;

      // Check if track already exists
      const existingTrack = await prisma.track.findFirst({
        where: {
          OR: [
            { spotifyId: spotifyTrack.id },
            { slug: trackSlug },
          ],
        },
      });

      if (existingTrack) {
        continue;
      }

      // Generate waveform data
      const waveform = generateWaveformData(
        spotifyTrack.duration_ms / 1000,
        spotifyTrack.id.charCodeAt(0) + spotifyTrack.track_number
      );

      // Create track
      await prisma.track.create({
        data: {
          slug: trackSlug,
          title: spotifyTrack.name,
          albumId: albumId,
          duration: Math.round(spotifyTrack.duration_ms / 1000),
          trackNumber: spotifyTrack.track_number,
          spotifyId: spotifyTrack.id,
          previewUrl: spotifyTrack.preview_url,
          isrc: spotifyTrack.external_ids?.isrc,
          waveform: waveform,
          isActive: true,
          order: spotifyTrack.track_number,
        },
      });

      created++;
    }

    return created;
  } catch (error) {
    console.error(`  Error fetching tracks for ${albumSlug}:`, error);
    return 0;
  }
}

async function main() {
  console.log("🎵 Fetching tracks from Spotify...\n");

  // Check for Spotify credentials
  if (!process.env.SPOTIFY_CLIENT_ID || !process.env.SPOTIFY_CLIENT_SECRET) {
    console.error("❌ Spotify credentials not configured!");
    console.error("   Please set SPOTIFY_CLIENT_ID and SPOTIFY_CLIENT_SECRET in .env");
    process.exit(1);
  }

  // Get all albums with Spotify URLs
  const albums = await prisma.album.findMany({
    where: {
      spotifyUrl: { not: null },
      isActive: true,
    },
    select: {
      id: true,
      slug: true,
      title: true,
      spotifyUrl: true,
      spotifyId: true,
      _count: {
        select: { tracks: true },
      },
    },
  });

  console.log(`Found ${albums.length} albums with Spotify URLs\n`);

  let totalCreated = 0;
  let processed = 0;
  let skipped = 0;
  let errors = 0;

  for (const album of albums) {
    // Skip albums that already have tracks
    if (album._count.tracks > 0) {
      console.log(`⏭️  Skipping ${album.title} (already has ${album._count.tracks} tracks)`);
      skipped++;
      continue;
    }

    // Extract Spotify album ID
    const spotifyAlbumId = album.spotifyId || extractSpotifyAlbumId(album.spotifyUrl!);

    if (!spotifyAlbumId) {
      console.log(`⚠️  Could not extract Spotify ID from: ${album.spotifyUrl}`);
      errors++;
      continue;
    }

    // Update album with spotifyId if not set
    if (!album.spotifyId) {
      await prisma.album.update({
        where: { id: album.id },
        data: { spotifyId: spotifyAlbumId },
      });
    }

    const created = await fetchTracksForAlbum(album.id, album.slug, spotifyAlbumId);
    totalCreated += created;
    processed++;

    console.log(`✅ ${album.title}: ${created} tracks created`);

    // Rate limiting - Spotify allows 180 requests per minute
    await new Promise((resolve) => setTimeout(resolve, 500));
  }

  console.log("\n" + "=".repeat(50));
  console.log("📊 Summary:");
  console.log(`   Albums processed: ${processed}`);
  console.log(`   Albums skipped: ${skipped}`);
  console.log(`   Albums with errors: ${errors}`);
  console.log(`   Total tracks created: ${totalCreated}`);

  // Get final stats
  const trackCount = await prisma.track.count();
  console.log(`\n📈 Total tracks in database: ${trackCount}`);

  await prisma.$disconnect();
}

main().catch((error) => {
  console.error("Fatal error:", error);
  process.exit(1);
});

/**
 * API Client for fetching data from our backend
 */

const API_BASE = "/api";

// Types for API responses
export interface ApiAlbum {
  id: string;
  slug: string;
  title: string;
  description: string | null;
  cover: string;
  coverBlur?: string;
  label: string;
  labelSlug?: string;
  releaseDate?: string;
  year?: number;
  spotifyUrl?: string;
  genres: Array<{ name: string; slug: string; color?: string }>;
  moods: Array<{ name: string; slug: string; color?: string }>;
  artists: Array<{ name: string; slug: string; role?: string }>;
  trackCount: number;
  isFeatured?: boolean;
}

export interface ApiTrack {
  id: string;
  slug: string;
  title: string;
  duration: number;
  bpm?: number;
  key?: string;
  isVocal: boolean;
  audioUrl: string | null;
  waveform: number[] | null;
  trackNumber?: number;
  albumId: string;
  albumTitle: string;
  albumSlug: string;
  albumCover: string;
  genres: string[];
  moods: string[];
  instruments?: string[];
  artists?: Array<{ name: string; slug: string }>;
}

export interface ApiArtist {
  id: string;
  slug: string;
  name: string;
  bio?: string;
  image: string;
  links: Array<{ platform: string; url: string; label?: string }>;
  albumCount: number;
  trackCount: number;
}

export interface ApiLabel {
  id: string;
  slug: string;
  name: string;
  description?: string;
  logo: string;
  website?: string;
  albumCount: number;
}

export interface ApiPlaylist {
  id: string;
  slug: string;
  title: string;
  description?: string;
  cover: string;
  category?: string;
  trackCount: number;
  isFeatured?: boolean;
}

export interface ApiGenre {
  id: string;
  name: string;
  slug: string;
  color?: string;
}

export interface ApiMood {
  id: string;
  name: string;
  slug: string;
  color?: string;
}

export interface PaginatedResponse<T> {
  pagination: {
    total: number;
    limit: number;
    offset: number;
    hasMore: boolean;
  };
}

// API Functions

export async function fetchAlbums(params?: {
  limit?: number;
  offset?: number;
  label?: string;
  genre?: string;
  featured?: boolean;
  sort?: "order" | "releaseDate" | "title";
}): Promise<{ albums: ApiAlbum[] } & PaginatedResponse<ApiAlbum>> {
  const searchParams = new URLSearchParams();
  if (params?.limit) searchParams.set("limit", params.limit.toString());
  if (params?.offset) searchParams.set("offset", params.offset.toString());
  if (params?.label) searchParams.set("label", params.label);
  if (params?.genre) searchParams.set("genre", params.genre);
  if (params?.featured) searchParams.set("featured", "true");
  if (params?.sort) searchParams.set("sort", params.sort);

  const res = await fetch(`${API_BASE}/albums?${searchParams}`);
  if (!res.ok) throw new Error("Failed to fetch albums");
  return res.json();
}

export async function fetchAlbum(idOrSlug: string): Promise<{
  album: ApiAlbum & { tracks: ApiTrack[] };
  similarAlbums: ApiAlbum[];
}> {
  const res = await fetch(`${API_BASE}/albums/${idOrSlug}`);
  if (!res.ok) throw new Error("Failed to fetch album");
  return res.json();
}

export async function fetchTracks(params?: {
  limit?: number;
  offset?: number;
  albumId?: string;
  genre?: string;
  mood?: string;
  instrument?: string;
  minBpm?: number;
  maxBpm?: number;
  minDuration?: number;
  maxDuration?: number;
  isVocal?: boolean;
}): Promise<{ tracks: ApiTrack[] } & PaginatedResponse<ApiTrack>> {
  const searchParams = new URLSearchParams();
  if (params?.limit) searchParams.set("limit", params.limit.toString());
  if (params?.offset) searchParams.set("offset", params.offset.toString());
  if (params?.albumId) searchParams.set("albumId", params.albumId);
  if (params?.genre) searchParams.set("genre", params.genre);
  if (params?.mood) searchParams.set("mood", params.mood);
  if (params?.instrument) searchParams.set("instrument", params.instrument);
  if (params?.minBpm) searchParams.set("minBpm", params.minBpm.toString());
  if (params?.maxBpm) searchParams.set("maxBpm", params.maxBpm.toString());
  if (params?.minDuration) searchParams.set("minDuration", params.minDuration.toString());
  if (params?.maxDuration) searchParams.set("maxDuration", params.maxDuration.toString());
  if (params?.isVocal !== undefined) searchParams.set("isVocal", params.isVocal.toString());

  const res = await fetch(`${API_BASE}/tracks?${searchParams}`);
  if (!res.ok) throw new Error("Failed to fetch tracks");
  return res.json();
}

export async function searchAll(query: string, type?: "all" | "albums" | "tracks" | "artists"): Promise<{
  albums: ApiAlbum[];
  tracks: ApiTrack[];
  artists: ApiArtist[];
  total: number;
  query: string;
}> {
  const searchParams = new URLSearchParams({ q: query });
  if (type) searchParams.set("type", type);

  const res = await fetch(`${API_BASE}/search?${searchParams}`);
  if (!res.ok) throw new Error("Failed to search");
  return res.json();
}

export async function fetchArtists(params?: {
  limit?: number;
  offset?: number;
  letter?: string;
}): Promise<{ artists: ApiArtist[] } & PaginatedResponse<ApiArtist>> {
  const searchParams = new URLSearchParams();
  if (params?.limit) searchParams.set("limit", params.limit.toString());
  if (params?.offset) searchParams.set("offset", params.offset.toString());
  if (params?.letter) searchParams.set("letter", params.letter);

  const res = await fetch(`${API_BASE}/artists?${searchParams}`);
  if (!res.ok) throw new Error("Failed to fetch artists");
  return res.json();
}

export async function fetchLabels(params?: {
  limit?: number;
  offset?: number;
}): Promise<{ labels: ApiLabel[] } & PaginatedResponse<ApiLabel>> {
  const searchParams = new URLSearchParams();
  if (params?.limit) searchParams.set("limit", params.limit.toString());
  if (params?.offset) searchParams.set("offset", params.offset.toString());

  const res = await fetch(`${API_BASE}/labels?${searchParams}`);
  if (!res.ok) throw new Error("Failed to fetch labels");
  return res.json();
}

export async function fetchPlaylists(params?: {
  limit?: number;
  offset?: number;
  category?: string;
  featured?: boolean;
}): Promise<{ playlists: ApiPlaylist[] } & PaginatedResponse<ApiPlaylist>> {
  const searchParams = new URLSearchParams();
  if (params?.limit) searchParams.set("limit", params.limit.toString());
  if (params?.offset) searchParams.set("offset", params.offset.toString());
  if (params?.category) searchParams.set("category", params.category);
  if (params?.featured) searchParams.set("featured", "true");

  const res = await fetch(`${API_BASE}/playlists?${searchParams}`);
  if (!res.ok) throw new Error("Failed to fetch playlists");
  return res.json();
}

export async function fetchGenres(): Promise<{ genres: ApiGenre[] }> {
  const res = await fetch(`${API_BASE}/genres`);
  if (!res.ok) throw new Error("Failed to fetch genres");
  return res.json();
}

export async function fetchMoods(): Promise<{ moods: ApiMood[] }> {
  const res = await fetch(`${API_BASE}/moods`);
  if (!res.ok) throw new Error("Failed to fetch moods");
  return res.json();
}

"use client";

import { useQuery } from "@tanstack/react-query";
import {
  fetchAlbums,
  fetchAlbum,
  fetchTracks,
  searchAll,
  fetchArtists,
  fetchLabels,
  fetchPlaylists,
  fetchGenres,
  fetchMoods,
} from "@/lib/api-client";

// Albums hooks
export function useAlbums(params?: Parameters<typeof fetchAlbums>[0]) {
  return useQuery({
    queryKey: ["albums", params],
    queryFn: () => fetchAlbums(params),
  });
}

export function useFeaturedAlbums(limit = 6) {
  return useQuery({
    queryKey: ["albums", "featured", limit],
    queryFn: () => fetchAlbums({ featured: true, limit }),
  });
}

export function useAlbum(idOrSlug: string) {
  return useQuery({
    queryKey: ["album", idOrSlug],
    queryFn: () => fetchAlbum(idOrSlug),
    enabled: !!idOrSlug,
  });
}

// Tracks hooks
export function useTracks(params?: Parameters<typeof fetchTracks>[0]) {
  return useQuery({
    queryKey: ["tracks", params],
    queryFn: () => fetchTracks(params),
  });
}

// Search hook
export function useSearch(query: string, type?: "all" | "albums" | "tracks" | "artists") {
  return useQuery({
    queryKey: ["search", query, type],
    queryFn: () => searchAll(query, type),
    enabled: query.length >= 2,
  });
}

// Artists hooks
export function useArtists(params?: Parameters<typeof fetchArtists>[0]) {
  return useQuery({
    queryKey: ["artists", params],
    queryFn: () => fetchArtists(params),
  });
}

// Labels hooks
export function useLabels(params?: Parameters<typeof fetchLabels>[0]) {
  return useQuery({
    queryKey: ["labels", params],
    queryFn: () => fetchLabels(params),
  });
}

// Playlists hooks
export function usePlaylists(params?: Parameters<typeof fetchPlaylists>[0]) {
  return useQuery({
    queryKey: ["playlists", params],
    queryFn: () => fetchPlaylists(params),
  });
}

export function useFeaturedPlaylists(limit = 4) {
  return useQuery({
    queryKey: ["playlists", "featured", limit],
    queryFn: () => fetchPlaylists({ featured: true, limit }),
  });
}

// Genres and Moods hooks
export function useGenres() {
  return useQuery({
    queryKey: ["genres"],
    queryFn: fetchGenres,
    staleTime: 1000 * 60 * 60, // Cache for 1 hour
  });
}

export function useMoods() {
  return useQuery({
    queryKey: ["moods"],
    queryFn: fetchMoods,
    staleTime: 1000 * 60 * 60, // Cache for 1 hour
  });
}

"use client";

import { QueryClient, QueryClientProvider } from "@tanstack/react-query";
import { useState, type ReactNode } from "react";

export function QueryProvider({ children }: { children: ReactNode }) {
  const [queryClient] = useState(
    () =>
      new QueryClient({
        defaultOptions: {
          queries: {
            staleTime: 1000 * 60 * 5, // 5 minutes
            refetchOnWindowFocus: false,
          },
        },
      })
  );

  return (
    <QueryClientProvider client={queryClient}>{children}</QueryClientProvider>
  );
}

