"use client";

import { useEffect, useRef, useState, useCallback } from "react";
import Image from "next/image";
import {
  Play,
  Pause,
  SkipBack,
  SkipForward,
  Volume2,
  VolumeX,
  X,
  Maximize2,
  AlertCircle,
} from "lucide-react";
import { motion, AnimatePresence } from "framer-motion";
import WaveSurfer from "wavesurfer.js";
import { usePlayerStore } from "@/stores/player-store";
import { formatDuration } from "@/lib/utils";
import { mockAlbums } from "@/lib/mock-data";
import { Waveform } from "./Waveform";

export function MiniPlayer() {
  const {
    currentTrack,
    isPlaying,
    volume,
    progress,
    duration,
    pause,
    resume,
    next,
    previous,
    setVolume,
    setProgress,
    setDuration,
    clearQueue,
  } = usePlayerStore();

  const waveformRef = useRef<HTMLDivElement>(null);
  const wavesurferRef = useRef<WaveSurfer | null>(null);
  const [isMuted, setIsMuted] = useState(false);
  const [isReady, setIsReady] = useState(false);
  const [isExpanded, setIsExpanded] = useState(false);
  const [hasError, setHasError] = useState(false);
  const [isLoading, setIsLoading] = useState(false);

  // Trouver l'album de la piste courante
  const currentAlbum = currentTrack
    ? mockAlbums.find((a) => a.id === currentTrack.albumId)
    : null;

  // Progress percentage for static waveform fallback
  const progressPercent = duration > 0 ? (progress / duration) * 100 : 0;

  // Initialiser WaveSurfer quand la piste change
  useEffect(() => {
    if (!waveformRef.current || !currentTrack) return;

    let isMounted = true;

    setIsReady(false);
    setHasError(false);
    setIsLoading(true);

    // Détruire l'instance précédente
    if (wavesurferRef.current) {
      try {
        wavesurferRef.current.destroy();
      } catch {
        // Ignore destroy errors
      }
      wavesurferRef.current = null;
    }

    // Créer une nouvelle instance WaveSurfer
    const wavesurfer = WaveSurfer.create({
      container: waveformRef.current,
      waveColor: "rgba(255, 255, 255, 0.3)",
      progressColor: "#1B9B4B",
      cursorColor: "#1B9B4B",
      cursorWidth: 2,
      barWidth: 2,
      barGap: 1,
      barRadius: 2,
      height: isExpanded ? 80 : 40,
      normalize: true,
      interact: true,
    });

    wavesurferRef.current = wavesurfer;

    // Event handlers
    wavesurfer.on("ready", () => {
      if (!isMounted) return;
      setDuration(wavesurfer.getDuration());
      wavesurfer.setVolume(isMuted ? 0 : volume);
      setIsReady(true);
      setIsLoading(false);
      setHasError(false);
      if (isPlaying) {
        wavesurfer.play().catch(() => {
          // Ignore play errors (user interaction required)
        });
      }
    });

    wavesurfer.on("error", (error) => {
      if (!isMounted) return;
      console.warn("WaveSurfer error:", error);
      setHasError(true);
      setIsLoading(false);
      // Set a default duration from mock data
      setDuration(currentTrack.duration);
    });

    wavesurfer.on("audioprocess", () => {
      if (!isMounted) return;
      setProgress(wavesurfer.getCurrentTime());
    });

    wavesurfer.on("seeking", () => {
      if (!isMounted) return;
      setProgress(wavesurfer.getCurrentTime());
    });

    wavesurfer.on("finish", () => {
      if (!isMounted) return;
      next();
    });

    // Charger l'audio avec gestion d'erreur
    try {
      wavesurfer.load(currentTrack.audioUrl);
    } catch (error) {
      console.warn("Failed to load audio:", error);
      if (isMounted) {
        setHasError(true);
        setIsLoading(false);
        setDuration(currentTrack.duration);
      }
    }

    return () => {
      isMounted = false;
      if (wavesurferRef.current) {
        try {
          wavesurferRef.current.destroy();
        } catch {
          // Ignore AbortError during cleanup

