      bpm,
      audioUrl: AUDIO_SAMPLES[audioIndex],
      albumId,
      genres: [GENRES[genreIndex]],
      moods: [MOODS[moodIndex]],
      instruments: [
        INSTRUMENTS[instrument1Index],
        INSTRUMENTS[instrument2Index],
      ],
      isVocal,
      waveform: generateWaveformData(100, baseSeed),
    };
  });
};

