// Parigo - Music Library Platform
// Database Schema for NeonDB (PostgreSQL)

generator client {
  provider = "prisma-client-js"
}

datasource db {
  provider  = "postgresql"
  url       = env("DATABASE_URL")
  directUrl = env("DIRECT_URL")
}

// ============================================
// ASSETS (Audio, Images)
// ============================================

model Asset {
  id          String    @id @default(cuid())
  path        String    @unique
  type        AssetType
  mimeType    String?
  size        Int?
  duration    Int?
  width       Int?
  height      Int?
  blurDataUrl String?   @db.Text
  createdAt   DateTime  @default(now())
  updatedAt   DateTime  @updatedAt

  // Relations
  trackAudio     Track[]    @relation("TrackAudio")
  albumCovers    Album[]    @relation("AlbumCover")
  artistImages   Artist[]   @relation("ArtistImage")
  labelLogos     Label[]    @relation("LabelLogo")
  playlistCovers Playlist[] @relation("PlaylistCover")

  @@index([path])
  @@index([type])
}

enum AssetType {
  AUDIO
  IMAGE
}

// ============================================
// GENRES, MOODS, INSTRUMENTS (Tags)
// ============================================

model Genre {
  id        String   @id @default(cuid())
  name      String   @unique
  slug      String   @unique
  color     String?
  order     Int      @default(0)
  isActive  Boolean  @default(true)
  createdAt DateTime @default(now())

  tracks TrackGenre[]
  albums AlbumGenre[]

  @@index([slug])
  @@index([isActive, order])
}

model Mood {
  id        String   @id @default(cuid())
  name      String   @unique
  slug      String   @unique
  color     String?
  order     Int      @default(0)
  isActive  Boolean  @default(true)
  createdAt DateTime @default(now())

  tracks TrackMood[]
  albums AlbumMood[]

  @@index([slug])
  @@index([isActive, order])
}

model Instrument {
  id        String   @id @default(cuid())
  name      String   @unique
  slug      String   @unique
  icon      String?
  order     Int      @default(0)
  isActive  Boolean  @default(true)
  createdAt DateTime @default(now())

  tracks TrackInstrument[]

  @@index([slug])
  @@index([isActive, order])
}

// ============================================
// LABELS
// ============================================

