"use client";

import { useEffect } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { Heart, Loader2 } from "lucide-react";
import { useSession } from "@/lib/auth-client";
import { useFavoritesStore } from "@/stores/favorites-store";
import { cn } from "@/lib/utils";

interface FavoriteButtonProps {
  type: "track" | "album" | "playlist";
  itemId: string;
  size?: "sm" | "md" | "lg";
  className?: string;
  showTooltip?: boolean;
}

export function FavoriteButton({
  type,
  itemId,
  size = "md",
  className,
  showTooltip = true,
}: FavoriteButtonProps) {
  const { data: session } = useSession();
  const {
    isLoading,
    isLoaded,
    loadFavorites,
    toggleFavoriteTrack,
    toggleFavoriteAlbum,
    toggleFavoritePlaylist,
    isTrackFavorite,
    isAlbumFavorite,
    isPlaylistFavorite,
  } = useFavoritesStore();

  // Load favorites when user is logged in
  useEffect(() => {
    if (session?.user && !isLoaded && !isLoading) {
      loadFavorites();
    }
  }, [session?.user, isLoaded, isLoading, loadFavorites]);

  // If not logged in, don't show the button (or show disabled)
  if (!session?.user) {
    return null;
  }

  const isFavorite =
    type === "track"
      ? isTrackFavorite(itemId)
      : type === "album"
      ? isAlbumFavorite(itemId)
      : isPlaylistFavorite(itemId);

  const handleToggle = async (e: React.MouseEvent) => {
    e.preventDefault();
    e.stopPropagation();

    if (type === "track") {
      await toggleFavoriteTrack(itemId);
    } else if (type === "album") {
      await toggleFavoriteAlbum(itemId);
    } else {
      await toggleFavoritePlaylist(itemId);
    }
  };

  const sizeClasses = {
    sm: "w-7 h-7",
    md: "w-9 h-9",
    lg: "w-11 h-11",
  };

  const iconSizes = {
    sm: 14,
    md: 18,
    lg: 22,
  };

  return (
    <div className="relative group">
      <motion.button
        onClick={handleToggle}
        disabled={isLoading}
        className={cn(
          "rounded-full flex items-center justify-center transition-all",
          "border-2 border-transparent",
          "hover:border-[var(--color-black)] hover:shadow-[2px_2px_0px_var(--color-black)]",
          "active:shadow-none active:translate-x-[2px] active:translate-y-[2px]",
          isFavorite
            ? "bg-red-100 text-red-500 hover:bg-red-200"
            : "bg-[var(--color-gray-100)] text-[var(--color-gray-400)] hover:text-red-500 hover:bg-red-50",
          sizeClasses[size],
          className
        )}
        whileTap={{ scale: 0.9 }}
        title={isFavorite ? "Retirer des favoris" : "Ajouter aux favoris"}
      >
        <AnimatePresence mode="wait">
          {isLoading ? (
            <motion.div
              key="loading"
              initial={{ opacity: 0, scale: 0.8 }}
              animate={{ opacity: 1, scale: 1 }}
              exit={{ opacity: 0, scale: 0.8 }}
            >
              <Loader2 size={iconSizes[size]} className="animate-spin" />
            </motion.div>
          ) : (
            <motion.div
              key={isFavorite ? "filled" : "empty"}
              initial={{ opacity: 0, scale: 0.5 }}
              animate={{ opacity: 1, scale: 1 }}
              exit={{ opacity: 0, scale: 0.5 }}
              transition={{ type: "spring", stiffness: 500, damping: 25 }}
            >
              <Heart
                size={iconSizes[size]}
                className={isFavorite ? "fill-current" : ""}
              />
            </motion.div>
          )}
        </AnimatePresence>
      </motion.button>

      {/* Tooltip */}
      {showTooltip && (
        <div className="absolute bottom-full left-1/2 -translate-x-1/2 mb-2 px-2 py-1 bg-[var(--color-black)] text-white text-xs rounded opacity-0 group-hover:opacity-100 transition-opacity whitespace-nowrap pointer-events-none">
          {isFavorite ? "Retirer des favoris" : "Ajouter aux favoris"}
        </div>
      )}
    </div>
  );
}

