     1→import { NextRequest, NextResponse } from "next/server";
     2→import { prisma } from "@/lib/prisma";
     3→import { getServerSession } from "@/lib/auth-utils";
     4→
     5→// GET - Get all favorite albums for the current user
     6→export async function GET() {
     7→  try {
     8→    const session = await getServerSession();
     9→    if (!session?.user) {
    10→      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    11→    }
    12→
    13→    const favorites = await prisma.favoriteAlbum.findMany({
    14→      where: { userId: session.user.id },
    15→      include: {
    16→        album: {
    17→          include: {
    18→            cover: { select: { path: true } },
    19→            label: { select: { name: true, slug: true } },
    20→            genres: {
    21→              include: { genre: { select: { name: true, slug: true } } },
    22→            },
    23→            _count: { select: { tracks: true } },
    24→          },
    25→        },
    26→      },
    27→      orderBy: { createdAt: "desc" },
    28→    });
    29→
    30→    const albums = favorites.map((fav) => ({
    31→      id: fav.album.id,
    32→      slug: fav.album.slug,
    33→      title: fav.album.title,
    34→      cover: fav.album.cover?.path || "/images/placeholder-album.jpg",
    35→      label: fav.album.label.name,
    36→      labelSlug: fav.album.label.slug,
    37→      genres: fav.album.genres.map((g) => ({ name: g.genre.name, slug: g.genre.slug })),
    38→      trackCount: fav.album._count.tracks,
    39→      favoritedAt: fav.createdAt,
    40→    }));
    41→
    42→    return NextResponse.json({ albums, total: albums.length });
    43→  } catch (error) {
    44→    console.error("Error fetching favorite albums:", error);
    45→    return NextResponse.json(
    46→      { error: "Failed to fetch favorites" },
    47→      { status: 500 }
    48→    );
    49→  }
    50→}
    51→
    52→// POST - Add an album to favorites
    53→export async function POST(request: NextRequest) {
    54→  try {
    55→    const session = await getServerSession();
    56→    if (!session?.user) {
    57→      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    58→    }
    59→
    60→    const { albumId } = await request.json();
    61→
    62→    if (!albumId) {
    63→      return NextResponse.json(
    64→        { error: "Album ID is required" },
    65→        { status: 400 }
    66→      );
    67→    }
    68→
    69→    // Check if album exists
    70→    const album = await prisma.album.findUnique({
    71→      where: { id: albumId },
    72→    });
    73→
    74→    if (!album) {
    75→      return NextResponse.json({ error: "Album not found" }, { status: 404 });
    76→    }
    77→
    78→    // Check if already favorited
    79→    const existing = await prisma.favoriteAlbum.findUnique({
    80→      where: {
    81→        userId_albumId: {
    82→          userId: session.user.id,
    83→          albumId,
    84→        },
    85→      },
    86→    });
    87→
    88→    if (existing) {
    89→      return NextResponse.json(
    90→        { error: "Album already in favorites" },
    91→        { status: 409 }
    92→      );
    93→    }
    94→
    95→    // Add to favorites
    96→    await prisma.favoriteAlbum.create({
    97→      data: {
    98→        userId: session.user.id,
    99→        albumId,
   100→      },
   101→    });
   102→
   103→    return NextResponse.json({ success: true, albumId });
   104→  } catch (error) {
   105→    console.error("Error adding favorite album:", error);
   106→    return NextResponse.json(
   107→      { error: "Failed to add favorite" },
   108→      { status: 500 }
   109→    );
   110→  }
   111→}
   112→
   113→// DELETE - Remove an album from favorites
   114→export async function DELETE(request: NextRequest) {
   115→  try {
   116→    const session = await getServerSession();
   117→    if (!session?.user) {
   118→      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
   119→    }
   120→
   121→    const { albumId } = await request.json();
   122→
   123→    if (!albumId) {
   124→      return NextResponse.json(
   125→        { error: "Album ID is required" },
   126→        { status: 400 }
   127→      );
   128→    }
   129→
   130→    // Delete from favorites
   131→    await prisma.favoriteAlbum.delete({
   132→      where: {
   133→        userId_albumId: {
   134→          userId: session.user.id,
   135→          albumId,
   136→        },
   137→      },
   138→    });
   139→
   140→    return NextResponse.json({ success: true, albumId });
   141→  } catch (error) {
