                              <span className="flex items-center gap-1">
                                <Music size={12} />
                                {artist.trackCount}
                              </span>
                            </div>
                          </div>
                        </Link>
                      </motion.div>
                    ))}
                  </div>
                </motion.div>
              ))}
          </div>
        )}
      </div>
    </div>
  );
}

