     1→/**
     2→ * Spotify API Client
     3→ * Uses Client Credentials flow for server-side access
     4→ */
     5→
     6→interface SpotifyToken {
     7→  access_token: string;
     8→  token_type: string;
     9→  expires_in: number;
    10→  expires_at?: number;
    11→}
    12→
    13→interface SpotifyTrack {
    14→  id: string;
    15→  name: string;
    16→  duration_ms: number;
    17→  track_number: number;
    18→  preview_url: string | null;
    19→  external_ids?: {
    20→    isrc?: string;
    21→  };
    22→  artists: Array<{
    23→    id: string;
    24→    name: string;
    25→  }>;
    26→}
    27→
    28→interface SpotifyAlbum {
    29→  id: string;
    30→  name: string;
    31→  release_date: string;
    32→  total_tracks: number;
    33→  images: Array<{
    34→    url: string;
    35→    height: number;
    36→    width: number;
    37→  }>;
    38→  tracks: {
    39→    items: SpotifyTrack[];
    40→    total: number;
    41→    next: string | null;
    42→  };
    43→}
    44→
    45→let cachedToken: SpotifyToken | null = null;
    46→
    47→/**
    48→ * Get Spotify access token using Client Credentials flow
    49→ */
    50→export async function getSpotifyToken(): Promise<string> {
