     1→"use client";
     2→
     3→import { useEffect, useRef, useState, useCallback } from "react";
     4→import Image from "next/image";
     5→import {
     6→  Play,
     7→  Pause,
     8→  SkipBack,
     9→  SkipForward,
    10→  Volume2,
    11→  VolumeX,
    12→  X,
    13→  Maximize2,
    14→  AlertCircle,
    15→} from "lucide-react";
    16→import { motion, AnimatePresence } from "framer-motion";
    17→import WaveSurfer from "wavesurfer.js";
    18→import { usePlayerStore } from "@/stores/player-store";
    19→import { formatDuration } from "@/lib/utils";
    20→import { Waveform } from "./Waveform";
    21→
    22→export function MiniPlayer() {
    23→  const {
    24→    currentTrack,
    25→    isPlaying,
    26→    volume,
    27→    progress,
    28→    duration,
    29→    pause,
    30→    resume,
    31→    next,
    32→    previous,
    33→    setVolume,
    34→    setProgress,
    35→    setDuration,
    36→    clearQueue,
    37→  } = usePlayerStore();
    38→
    39→  const waveformRef = useRef<HTMLDivElement>(null);
    40→  const wavesurferRef = useRef<WaveSurfer | null>(null);
    41→  const [isMuted, setIsMuted] = useState(false);
    42→  const [isReady, setIsReady] = useState(false);
    43→  const [isExpanded, setIsExpanded] = useState(false);
    44→  const [hasError, setHasError] = useState(false);
    45→  const [isLoading, setIsLoading] = useState(false);
    46→
    47→  // Get album info from track
    48→  const albumCover = currentTrack?.albumCover;
    49→  const albumTitle = currentTrack?.albumTitle;
    50→
    51→  // Progress percentage for static waveform fallback
    52→  const progressPercent = duration > 0 ? (progress / duration) * 100 : 0;
    53→
    54→  // Initialiser WaveSurfer quand la piste change
    55→  useEffect(() => {
    56→    if (!waveformRef.current || !currentTrack) return;
    57→
    58→    let isMounted = true;
    59→
    60→    setIsReady(false);
    61→    setHasError(false);
    62→    setIsLoading(true);
    63→
    64→    // Détruire l'instance précédente
    65→    if (wavesurferRef.current) {
    66→      try {
    67→        wavesurferRef.current.destroy();
    68→      } catch {
    69→        // Ignore destroy errors
    70→      }
    71→      wavesurferRef.current = null;
    72→    }
    73→
    74→    // Créer une nouvelle instance WaveSurfer
    75→    const wavesurfer = WaveSurfer.create({
    76→      container: waveformRef.current,
    77→      waveColor: "rgba(255, 255, 255, 0.3)",
    78→      progressColor: "#1B9B4B",
    79→      cursorColor: "#1B9B4B",
    80→      cursorWidth: 2,
    81→      barWidth: 2,
    82→      barGap: 1,
    83→      barRadius: 2,
    84→      height: isExpanded ? 80 : 40,
    85→      normalize: true,
    86→      interact: true,
    87→    });
    88→
    89→    wavesurferRef.current = wavesurfer;
    90→
    91→    // Event handlers
    92→    wavesurfer.on("ready", () => {
    93→      if (!isMounted) return;
    94→      setDuration(wavesurfer.getDuration());
    95→      wavesurfer.setVolume(isMuted ? 0 : volume);
    96→      setIsReady(true);
    97→      setIsLoading(false);
    98→      setHasError(false);
    99→      if (isPlaying) {
   100→        wavesurfer.play().catch(() => {
   101→          // Ignore play errors (user interaction required)
   102→        });
   103→      }
   104→    });
   105→
   106→    wavesurfer.on("error", (error) => {
   107→      if (!isMounted) return;
   108→      console.warn("WaveSurfer error:", error);
   109→      setHasError(true);
   110→      setIsLoading(false);
   111→      // Set a default duration from mock data
   112→      setDuration(currentTrack.duration);
   113→    });
   114→
   115→    wavesurfer.on("audioprocess", () => {
   116→      if (!isMounted) return;
   117→      setProgress(wavesurfer.getCurrentTime());
   118→    });
   119→
   120→    wavesurfer.on("seeking", () => {
   121→      if (!isMounted) return;
   122→      setProgress(wavesurfer.getCurrentTime());
   123→    });
   124→
   125→    wavesurfer.on("finish", () => {
   126→      if (!isMounted) return;
   127→      next();
   128→    });
   129→
   130→    // Charger l'audio avec gestion d'erreur
   131→    if (!currentTrack.audioUrl) {
   132→      // No audio URL available
   133→      setHasError(true);
   134→      setIsLoading(false);
   135→      setDuration(currentTrack.duration);
   136→      return;
   137→    }
   138→
   139→    try {
   140→      wavesurfer.load(currentTrack.audioUrl);
   141→    } catch (error) {
   142→      console.warn("Failed to load audio:", error);
   143→      if (isMounted) {
   144→        setHasError(true);
   145→        setIsLoading(false);
   146→        setDuration(currentTrack.duration);
   147→      }
   148→    }
   149→
   150→    return () => {
   151→      isMounted = false;
   152→      if (wavesurferRef.current) {
   153→        try {
   154→          wavesurferRef.current.destroy();
   155→        } catch {
   156→          // Ignore AbortError during cleanup
   157→        }
   158→        wavesurferRef.current = null;
   159→      }
   160→    };
   161→  }, [currentTrack?.id]);
   162→
   163→  // Gérer play/pause
   164→  useEffect(() => {
   165→    if (!wavesurferRef.current || !isReady) return;
   166→
   167→    if (isPlaying) {
   168→      wavesurferRef.current.play().catch(() => {
   169→        // Ignore play errors
   170→      });
   171→    } else {
   172→      wavesurferRef.current.pause();
   173→    }
   174→  }, [isPlaying, isReady]);
   175→
   176→  // Gérer le volume
   177→  useEffect(() => {
   178→    if (wavesurferRef.current) {
   179→      wavesurferRef.current.setVolume(isMuted ? 0 : volume);
   180→    }
   181→  }, [volume, isMuted]);
   182→
   183→  // Redimensionner le waveform quand on expand
   184→  useEffect(() => {
   185→    if (wavesurferRef.current && isReady) {
   186→      wavesurferRef.current.setOptions({
   187→        height: isExpanded ? 80 : 40,
   188→      });
   189→    }
